<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import http from'../../api/http';const no=ref(''),data=ref<any>(null);async function load(){if(!no.value)return ElMessage.warning('请输入销售订单号');const r=await http.get(`/erp/order-costs/${no.value}`);data.value=r.data.data}</script><template><section><h1>订单成本与毛利</h1><p>按销售订单汇总收入、材料与费用成本，计算毛利及毛利率。</p><el-card shadow="never"><div class="search"><el-input v-model="no" placeholder="销售订单号"/><el-button type="primary" @click="load">分析</el-button></div><el-descriptions v-if="data" :column="5" border><el-descriptions-item label="销售订单">{{data.salesOrderNo}}</el-descriptions-item><el-descriptions-item label="收入">{{data.revenue}}</el-descriptions-item><el-descriptions-item label="成本">{{data.cost}}</el-descriptions-item><el-descriptions-item label="毛利">{{data.grossMargin}}</el-descriptions-item><el-descriptions-item label="毛利率">{{data.grossMarginRate}}%</el-descriptions-item></el-descriptions><el-empty v-else description="输入订单号查看成本和毛利"/></el-card></section></template><style scoped>h1{color:#263f5c}p{color:#8391a4}.search{display:flex;gap:8px;margin-bottom:20px}.search .el-input{width:320px}</style>
